import { Buffer } from "node:buffer";
import { z } from "zod";
import { failure, runtimeFailureSchema, } from "./failures.js";
import { RUNTIME_LIMITS } from "./limits.js";
export const jsonValueSchema = z.json();
export const jobIdSchema = z
    .string()
    .min(1)
    .max(128)
    .regex(/^[A-Za-z0-9._-]+$/);
export const stdioEntrySchema = z
    .object({
    stream: z.enum(["stdout", "stderr"]),
    text: z.string(),
})
    .strict();
const browserCodeSchema = z
    .string()
    .refine((code) => Buffer.byteLength(code, "utf8") <= RUNTIME_LIMITS.codeBytes, "Code exceeds the 64 KiB limit");
export const browserJobInputSchema = z
    .object({
    code: browserCodeSchema,
    timeoutMs: z.number().int().positive().max(RUNTIME_LIMITS.timeoutMs).optional(),
})
    .strict();
export const proxyEndpointSchema = z
    .string()
    .url()
    .refine((value) => {
    const url = new URL(value);
    return ((url.protocol === "ws:" || url.protocol === "wss:") &&
        url.username === "" &&
        url.password === "");
}, "Expected a credential-free WebSocket endpoint");
const defaultTimeoutsSchema = z
    .object({
    actionMs: z.number().int().nonnegative(),
    navigationMs: z.number().int().nonnegative(),
})
    .strict();
export const workerRequestSchema = z
    .object({
    kind: z.literal("run"),
    id: jobIdSchema,
    code: browserCodeSchema,
    timeoutMs: z.number().int().positive().max(RUNTIME_LIMITS.timeoutMs),
    proxyEndpoint: proxyEndpointSchema,
    defaultTimeouts: defaultTimeoutsSchema.optional(),
    pageGuid: z.string().min(1).max(128).optional(),
})
    .strict();
export const workerFrameSchema = z.discriminatedUnion("kind", [
    z
        .object({
        kind: z.literal("stdio"),
        id: jobIdSchema,
        entry: stdioEntrySchema,
    })
        .strict(),
    z
        .object({
        kind: z.literal("result"),
        id: jobIdSchema,
        outcome: z.discriminatedUnion("kind", [
            z
                .object({
                kind: z.literal("success"),
                value: jsonValueSchema,
            })
                .strict(),
            z
                .object({
                kind: z.literal("failure"),
                failure: runtimeFailureSchema,
            })
                .strict(),
        ]),
    })
        .strict(),
]);
export function admitBrowserJob(input) {
    const parsed = browserJobInputSchema.safeParse(input);
    if (!parsed.success) {
        return {
            kind: "rejected",
            failure: failure("invalid_input", "Browser job input was rejected"),
        };
    }
    return { kind: "admitted", value: parsed.data };
}
export function encodeNdjson(value) {
    return Buffer.from(`${JSON.stringify(value)}\n`, "utf8");
}
export class NdjsonDecoder {
    constructor(schema, maxFrameBytes = RUNTIME_LIMITS.ndjsonFrameBytes) {
        this.schema = schema;
        this.maxFrameBytes = maxFrameBytes;
        this.buffer = Buffer.alloc(0);
    }
    push(chunk) {
        this.buffer = Buffer.concat([this.buffer, Buffer.from(chunk)]);
        if (this.buffer.length > this.maxFrameBytes && this.buffer.indexOf(0x0a) === -1) {
            return {
                kind: "rejected",
                failure: failure("limit_exceeded", "NDJSON frame limit exceeded"),
            };
        }
        const values = [];
        let newline = this.buffer.indexOf(0x0a);
        while (newline !== -1) {
            if (newline > this.maxFrameBytes) {
                return {
                    kind: "rejected",
                    failure: failure("limit_exceeded", "NDJSON frame limit exceeded"),
                };
            }
            const line = this.buffer.subarray(0, newline);
            this.buffer = this.buffer.subarray(newline + 1);
            if (line.length > 0) {
                const parsed = this.parseLine(line);
                if (parsed.kind === "rejected") {
                    return parsed;
                }
                values.push(parsed.value);
            }
            newline = this.buffer.indexOf(0x0a);
        }
        return { kind: "admitted", value: values };
    }
    finish() {
        if (this.buffer.length === 0) {
            return { kind: "admitted", value: undefined };
        }
        return {
            kind: "rejected",
            failure: failure("protocol_violation", "Incomplete NDJSON frame"),
        };
    }
    parseLine(line) {
        try {
            const parsed = this.schema.safeParse(JSON.parse(Buffer.from(line).toString("utf8")));
            if (!parsed.success) {
                return {
                    kind: "rejected",
                    failure: failure("protocol_violation", "Invalid NDJSON frame"),
                };
            }
            return { kind: "admitted", value: parsed.data };
        }
        catch {
            return {
                kind: "rejected",
                failure: failure("protocol_violation", "Malformed NDJSON frame"),
            };
        }
    }
}
